function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 300000) return 's needs 1 to 300000 characters.';
  if (/[^0-9+\-*\/ ]/.test(s)) return 's may contain only digits, spaces and + - * /.';
  const tokens = s.match(/\d+|[+\-*\/]/g) ?? [];
  if (tokens.length % 2 === 0) return 's must be a valid expression that starts and ends with a number.';
  for (let i = 0; i < tokens.length; i++) {
    if (/^\d/.test(tokens[i]) !== (i % 2 === 0)) return 'Numbers and operators must alternate.';
  }
  const low = -(2 ** 31), high = 2 ** 31 - 1;
  let total = 0;
  let term = Number(tokens[0]);
  if (term > high) return 'Each integer is at most 2^31 - 1.';
  for (let i = 1; i < tokens.length; i += 2) {
    const op = tokens[i], value = Number(tokens[i + 1]);
    if (value > high) return 'Each integer is at most 2^31 - 1.';
    if (op === '+' || op === '-') { total += term; term = op === '+' ? value : -value; }
    else if (op === '*') term *= value;
    else if (value === 0) return 'The expression must not divide by zero.';
    else term = Math.trunc(term / value);
    if (term < low || term > high || total + term < low || total + term > high) return 'Every intermediate result must fit in a 32-bit signed integer.';
  }
  return null;
}

