function calculate(s) {
  const stack = [];
  let number = 0;
  let operator = '+';

  for (let i = 0; i < s.length; i++) {
    const char = s[i];
    const isDigit = char >= '0' && char <= '9';
    if (isDigit) {
      number = number * 10 + Number(char);
    }
    if ((!isDigit && char !== ' ') || i === s.length - 1) {
      if (operator === '+') {
        stack.push(number);
      } else if (operator === '-') {
        stack.push(-number);
      } else if (operator === '*') {
        stack.push(stack.pop() * number);
      } else {
        stack.push(Math.trunc(stack.pop() / number));
      }
      operator = char;
      number = 0;
    }
  }

  let result = 0;
  for (const value of stack) {
    result += value;
  }
  return result;
}

