function calculate(s) {
  // Tokenise, collapse the leftmost * or / until none is left, then add and subtract left to right.
  const tokens = s.replace(/ /g, '').match(/\d+|[+\-*\/]/g).map(t => /\d/.test(t) ? Number(t) : t);
  for (;;) {
    const at = tokens.findIndex(t => t === '*' || t === '/');
    if (at < 0) break;
    const a = tokens[at - 1], b = tokens[at + 1];
    tokens.splice(at - 1, 3, tokens[at] === '*' ? a * b : Math.floor(a / b));
  }
  let value = tokens[0];
  for (let i = 1; i < tokens.length; i += 2) value = tokens[i] === '+' ? value + tokens[i + 1] : value - tokens[i + 1];
  return value;
}

